",\n      \"name\": \"Serkans LED-Taschenlampe\",\n      \"traeger\": \"serkan\",\n      \"farbe\": \"#FFFFFF\",\n      \"radius\": 3.0,\n      \"an\": [\n        [\n          \"23:56:00\",\n          \"00:01:00\"\n        ]\n      ],\n      \"hinweis\": \"im Windfang hinter geschlossener Innentür, erreicht den Saal nicht\"\n    },\n    {\n      \"id\": \"licht_notlaterne\",\n      \"art\": \"lampe\",\n      \"name\": \"Notlaterne am Haken im Vorratsraum\",\n      \"ort\": \"vorrat_innen\",\n      \"farbe\": \"#FFF1C9\",\n      \"radius\": 3.0,\n      \"an\": [],\n      \"hinweis\": \"Wird in der Tatnacht nie eingeschaltet; Herr Schneider erreicht sie nicht.\"\n    }\n  ],\n  \"luftzug\": [\n    {\n      \"ab\": \"23:30\",\n      \"weg\": [\n        \"thekensaal\",\n        \"durchgang\",\n        \"west_saal\"\n      ],\n      \"grund\": \"Seit dem Qualm stehen die Lichtschacht-Klappen offen; Kaminschacht und Lichtschächte ziehen Luft aus dem Buffetsaal durch den Durchgang in den Kaminsaal.\"\n    }\n  ],\n  \"geraeusch\": {\n    \"regel\": \"Nachbarschaft der Räume für das Hören. Die Hörregeln (sehr laut, laut, leise, Tumult) stehen in wahrnehmung.json.\",\n    \"nachbarn\": [\n      [\n        \"thekensaal\",\n        \"vorratsraum\"\n      ],\n      [\n        \"thekensaal\",\n        \"durchgang\"\n      ],\n      [\n        \"durchgang\",\n        \"west_saal\"\n      ],\n      [\n        \"thekensaal\",\n        \"ost_saal\"\n      ],\n      [\n        \"west_saal\",\n        \"turmgang\"\n      ],\n      [\n        \"thekensaal\",\n        \"windfang\"\n      ]\n    ],\n    \"geschlossen\": [\n      [\n        \"thekensaal\",\n        \"windfang\"\n      ]\n    ]\n  }\n}",
  "wahrnehmung.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Regeln für Wege und Wahrnehmung in der Tatnacht. Startwerte aus 7.4, verfeinert per Denkprotokoll (E-015). Der Plausibilitätsprüfer rechnet damit jede Wahrnehmung aus der Tatmatrix aus.\",\n  \"tempo\": {\n    \"dunkel\": 1.0,\n    \"hell\": 1.5,\n    \"rennen\": 2.5,\n    \"regel\": \"Gehen im Dunkeln höchstens 1 m/s, bei Licht höchstens 1,5 m/s. Rennen höchstens 2,5 m/s und nie lautlos. Als hell gilt ein Weg nur, wenn Start und Ziel volles oder schwaches Licht haben.\"\n  },\n  \"licht\": {\n    \"voll\": [\n      \"elektrisch\"\n    ],\n    \"schwach\": [\n      \"kerze\",\n      \"lampe\",\n      \"feuer\"\n    ],\n    \"rest\": [\n      \"notlicht\",\n      \"nachleuchten\"\n    ],\n    \"erkennenSchwachBis\": 3.0,\n    \"regel\": \"Sehen braucht Licht am Ziel und eine freie Sichtlinie. Bei vollem Licht erkennt man Personen im ganzen Raum. Bei schwachem Licht erkennt man Gesicht und Farben bis 3 m, weiter weg nur Umrisse. Restlicht zeigt nur Umrisse. Etwas, das selbst leuchtet (die Maske), sieht man im Dunkeln auch von weitem, aber nur als leuchtendes Gesicht. Wer kauert, liegt oder die Augen verbunden hat, sieht nichts.\"\n  },\n  \"hoeren\": {\n    \"klassen\": {\n      \"sehr_laut\": \"im selben Raum und in jedem direkt angrenzenden Raum hinter offener oder angelehnter Tür; auch durch Kopfhörer mit Musik; zwei Räume weiter nicht\",\n      \"laut\": \"im selben Raum; im Nachbarraum nur bis 3 m von der offenen Tür\",\n      \"leise\": \"im selben Raum bis 3 m\"\n    },\n    \"tumult\": {\n      \"von\": \"23:58:00\",\n      \"bis\": \"00:00:00\",\n      \"raeume\": [\n        \"thekensaal\",\n        \"durchgang\",\n        \"ost_saal\"\n      ],\n      \"lautBis\": 3.0,\n      \"leiseBis\": 1.5,\n      \"regel\": \"Im Tumult rufen alle durcheinander. Lautes hört man dort nur bis 3 m, Leises nur bis 1,5 m. Sehr Lautes hört man weiter überall.\"\n    },\n    \"zweiTueren\": \"Zwei Räume weiter oder hinter einer geschlossenen Tür hört man nichts Genaues.\",\n    \"schritte\": {\n      \"gehen\": \"leise\",\n      \"rennen\": \"laut\"\n    },\n    \"liegend\": \"Wer bewusstlos liegt, hört nichts.\",\n    \"bund\": \"Wer den Schlüsselbund trägt, hält ihn fest in der Faust. Er klimpert nur, als er vom Gürtel gezogen wird.\",\n    \"tueren\": \"Eine offene Tür quietscht nicht, wenn man hindurchgeht. Wird eine quietschende Tür geöffnet oder geschlossen, ist das laut.\",\n    \"hindernisse\": \"Möbel wie Theke und Tische dämpfen nicht; es zählen nur Räume, Türen und Abstand.\"\n  },\n  \"fuehlen\": {\n    \"bis\": 1.0,\n    \"regel\": \"Berührung bis 1 m. Man spürt, dass jemand da ist oder vorbeidrängt, aber nicht, wer. Wer es ist, weiß man nur, wenn die Person etwas sagt.\"\n  },\n  \"riechen\": {\n    \"nachwirkenSekunden\": 90,\n    \"regel\": \"Im selben Raum oder in Räumen, in die der Luftzug den Geruch trägt.\"\n  },\n  \"haltungen\": {\n    \"steht\": {\n      \"sieht\": true,\n      \"hoert\": \"alles\"\n    },\n    \"sitzt\": {\n      \"sieht\": true,\n      \"hoert\": \"alles\"\n    },\n    \"kauert\": {\n      \"sieht\": false,\n      \"hoert\": \"alles\"\n    },\n    \"augenbinde\": {\n      \"sieht\": false,\n      \"hoert\": \"nur_sehr_laut\"\n    },\n    \"liegt\": {\n      \"sieht\": false,\n      \"hoert\": \"nichts\"\n    }\n  },\n  \"abtastung\": {\n    \"sekunden\": 1,\n    \"matrixSchritt\": 15,\n    \"fenster\": [\n      \"23:55:00\",\n      \"00:05:00\"\n    ],\n    \"planFenster\": [\n      \"23:50:00\",\n      \"00:15:00\"\n    ]\n  },\n  \"zeitgefuehl\": \"Im Dunkeln schätzt niemand Zeitabstände verlässlich. Als Wissen zählt nur die Reihenfolge von Ereignissen, die eine Person selbst wahrgenommen hat.\"\n}",
  "figuren.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Kanon der Figuren. IDs aus Behzads JSON bleiben Schlüssel, auch wenn der Anzeigename wegen der Namensbalance wechselt (E-014). Koordinaten in Metern auf dem Raster aus raeume.json; sie zeigen den Platz während der Ermittlungsrunden. Positionen in der Tatnacht stehen in den Tatmatrix-Dateien.\",\n  \"detektiv\": {\n    \"id\": \"detective\",\n    \"title\": \"Der Detektiv / Die Detektivin (Gast)\",\n    \"selectableGenders\": [\n      \"m\",\n      \"w\"\n    ],\n    \"colorCode\": \"#B8A48A\",\n    \"farbname\": \"Sandbeige\",\n    \"startRoom\": \"ost_saal\",\n    \"ermittlungsOrt\": \"geburtstagsplatz\",\n    \"coordinates\": {\n      \"x\": 24.5,\n      \"y\": 16.5\n    },\n    \"visualSpecs\": {\n      \"silhouette\": \"Mittelgroß, aufmerksame Haltung, Kopf leicht schief beim Zuhören\",\n      \"baseOutfit\": \"Heller sandbeiger Trenchcoat über Alltagskleidung, schwarze Jeans, dunkle Turnschuhe\",\n      \"accessories\": [\n        \"Markante Brille\",\n        \"Braun karierter Detektivhut\",\n        \"Unangezündete Pfeife, aus der Seifenblasen steigen\"\n      ],\n      \"interactiveTool\": \"Handy in der Hand mit Taschenlampen-Lichtkegel\",\n      \"idleAnimation\": \"Bläst mit der Pfeife ein paar Seifenblasen und tippt aufs Handy\"\n    },\n    \"tatnacht\": \"Ab 23:55 sitzt der Detektiv als blinde Kuh mit verbundenen Augen und Kopfhörern im Ost-Saal auf dem Ehrenplatz. Die Musik läuft laut. Durch die Musik hört er nur den Knall, Herrn Schneiders Rufe „Hab ich dich!“ und „Stehen bleiben!“ und später ein Scheppern.\",\n    \"auftrag\": \"Um 0:20 bittet Herr Schneider den Detektiv: „Finde raus, wer das war. Bis zum Morgen.“\",\n    \"nieVerdaechtig\": true,\n    \"look\": {\n      \"haut\": \"#d9a983\",\n      \"haar\": \"#4a3222\",\n      \"kopf\": \"detektivhut\",\n      \"statur\": \"normal\",\n      \"schnitt\": \"suit\"\n    }\n  },\n  \"opfer\": {\n    \"id\": \"schneider\",\n    \"name\": \"Herr Schneider\",\n    \"age\": 61,\n    \"geschlecht\": \"m\",\n    \"roleTitle\": \"Schlossverwalter\",\n    \"isNpc\": true,\n    \"colorCode\": \"#2E473B\",\n    \"farbname\": \"Dunkelgrün\",\n    \"startRoom\": \"thekensaal\",\n    \"ermittlungsOrt\": \"hinter_rechtem_buffet\",\n    \"coordinates\": {\n      \"x\": 18.5,\n      \"y\": 13.5\n    },\n    \"status\": \"Nach dem Schlag kurz bewusstlos. Er wacht um 0:01:30 auf, hat eine Beule und eine Gedächtnislücke für die Sekunden vor dem Schlag. Danach sitzt er mit einem Kühlpack im Buffetsaal und ist bald wieder grantig.\",\n    \"visualSpecs\": {\n      \"silhouette\": \"Breiter, leicht gebeugter Körperbau, Halbglatze, Brille, graues schütteres Haar\",\n      \"outfit\": \"Dunkelgrüne Wachsjacke über grobem grauem Rollkragenpullover, derbe Arbeitsstiefel\",\n      \"distinguishingFeature\": \"Großer klimpernder Schlüsselbund an der rechten Gürtelschlaufe, Klemmbrett mit Quittungsblock\",\n      \"idleAnimation\": \"Tippt auf die Armbanduhr und hakt etwas auf dem Klemmbrett ab\"\n    },\n    \"motiveAndConflict\": \"Seit 25 Jahren hält er das Schloss in Schuss. Den Keller hat er Ahmet umsonst überlassen. Heute ärgert er sich über die Tür, den Parkplatz, die Musik und die offene Vitrine. Um zwölf will er alles klären.\",\n    \"warmeSeite\": \"Er hat den Messingkerzenständer selbst poliert, weil er Feste mag. Kleine Schäden zahlt er oft aus eigener Tasche.\",\n    \"erinnerung\": \"Knall, Dunkelheit, der Weg zur Notlaterne, ein leuchtendes Gespenstergesicht. Er packt eine Kapuze und ruft „Hab ich dich!“. Danach ist alles weg.\",\n    \"schluesselbund\": \"bund_schneider\",\n    \"gedaechtnisLueckeAb\": \"23:58:14\",\n    \"look\": {\n      \"haut\": \"#e8c9b0\",\n      \"haar\": \"#9a9a9a\",\n      \"kopf\": \"none\",\n      \"statur\": \"broad\",\n      \"schnitt\": \"suit\",\n      \"glatze\": true\n    },\n    \"schluesselbundMaterial\": \"Schlüssel aus dunklem Eisen an einem Stahlring, kein Messing.\"\n  },\n  \"figuren\": [\n    {\n      \"id\": \"ahmet\",\n      \"name\": \"Ahmet\",\n      \"aussprache\": \"Achmet\",\n      \"age\": 27,\n      \"geschlecht\": \"m\",\n      \"herkunft\": \"bosnisch\",\n      \"tier\": 1,\n      \"besetzungsplatz\": 1,\n      \"minPlayers\": 1,\n      \"roleTitle\": \"Der Organisator\",\n      \"isPotentialKiller\": true,\n      \"colorCode\": \"#1A1A1A\",\n      \"farbname\": \"Schwarz und Weiß\",\n      \"startRoom\": \"thekensaal\",\n      \"ermittlungsOrt\": \"vor_theke\",\n      \"coordinates\": {\n        \"x\": 14.5,\n        \"y\": 10.5\n      },\n      \"visualSpecs\": {\n        \"silhouette\": \"Schlank, aufrecht, sportliche Haltung, Brille, kurzer Bart\",\n        \"outfit\": \"Schwarzer Strickpulli über weißem T-Shirt, dunkle Jeans, weiße Turnschuhe. Die schwarze Stoffjacke hängt ab 23:55 am Jackenständer im Ost-Saal.\",\n        \"distinguishingFeature\": \"Blaues Stoffarmband am Handgelenk, Handy in der Hand (ab 0:05, vorher im Handykorb)\",\n        \"idleAnimation\": \"Dreht am blauen Stoffarmband und streicht sich nervös durch den Bart\"\n      },\n      \"motiveAndConflict\": \"Ahmet hat den Keller umsonst bekommen. Dafür gestaltet er das Programm des Adventsmarkts. Beim Essen hat er viel zu groß bestellt. Statt das zuzugeben, hat er von allen 150 € „Miete“ eingesammelt. Um 23:51 sagt Herr Schneider an der Theke: „Um zwölf sag ich allen, was der Keller gekostet hat.“\",\n      \"blackoutAlibi\": \"Behauptet, hinter der Theke nach Servietten gesucht zu haben.\",\n      \"roleSecret\": \"Um 23:57 schlüpft er mit dem Umschlag voller Mietgeld hinter die Theke. Er will Herrn Schneider bitten, um zwölf nichts zu sagen. Das Geld will er morgen allen zurückgeben.\",\n      \"persoenlichesZiel\": \"Niemand soll vor dem Morgen erfahren, dass die Miete erfunden war.\",\n      \"nebendelikt\": {\n        \"id\": \"nd_mietgeld\",\n        \"text\": \"Hat von allen 150 € Miete kassiert, obwohl der Keller nichts gekostet hat.\"\n      },\n      \"loyalitaet\": {\n        \"zu\": \"leyla\",\n        \"grund\": \"Sie sind zusammen aufgewachsen und halten zusammen.\"\n      },\n      \"luegen\": [\n        {\n          \"id\": \"luege_ahmet_servietten\",\n          \"behauptung\": \"Ich hab hinter der Theke nur Servietten gesucht.\",\n          \"wahrheit\": \"Er wollte Herrn Schneider mit dem Umschlag um Aufschub bitten.\",\n          \"duWahrheit\": \"Du wolltest Herrn Schneider mit dem Umschlag um Aufschub bitten.\"\n        },\n        {\n          \"id\": \"luege_ahmet_miete\",\n          \"behauptung\": \"Die 150 € waren für die Miete.\",\n          \"wahrheit\": \"Der Keller hat nichts gekostet; das Geld deckt seine zu große Essensbestellung.\",\n          \"duWahrheit\": \"Der Keller hat nichts gekostet. Das Geld deckt deine zu große Essensbestellung.\"\n        }\n      ],\n      \"innocentProfile\": {\n        \"actualBehavior\": \"Duckt sich beim Knall hinter der Theke am Ostende neben Damir und hält den Umschlag fest. Er bleibt dort, bis das Licht angeht. Später leert er den Umschlag und wirft ihn in den Ascheneimer am Kamin.\"\n      },\n      \"killerProfile\": {\n        \"crimeExecution\": \"Er kauert erst am Ostende der Theke neben Damir. Dann geht er zum Kerzenlicht an der Anrichte, um Herrn Schneider zu bitten. Herr Schneider, noch außer sich wegen Can, packt ihn am Arm und zischt: „Um zwölf erfahren's alle.“ In Panik greift Ahmet mit der Hand, in der er den Umschlag hält, den Kerzenständer und schlägt einmal zu. Heißes Wachs tropft auf den Umschlag, eine Ecke reißt ab und bleibt am Griff kleben. In Panik reißt er den Bund vom Gürtel: Wer den Schlüssel hat, kommt raus, bevor das Licht angeht. Gleich danach merkt er, dass Flucht alles schlimmer macht. Er steckt den Bund im Ost-Saal in seine eigene Jacke und kauert sich wieder neben Damir.\",\n        \"smokingGun\": \"Im Wachs am Griff des Kerzenständers klebt eine abgerissene Ecke seines Mietumschlags.\",\n        \"zusatzindiz\": \"Rote Wachstropfen auf dem leeren Umschlag im Ascheneimer am Kamin; eine Ecke fehlt.\"\n      },\n      \"look\": {\n        \"haut\": \"#d9a983\",\n        \"haar\": \"#1a1412\",\n        \"kopf\": \"none\",\n        \"statur\": \"slim\",\n        \"schnitt\": \"suit\"\n      },\n      \"alltag\": \"Arbeitet in einer Agentur, die Stadtfeste und Märkte plant.\"\n    },\n    {\n      \"id\": \"fatma\",\n      \"name\": \"Fatma\",\n      \"aussprache\": \"Fatma\",\n      \"age\": 26,\n      \"geschlecht\": \"w\",\n      \"herkunft\": \"kurdisch\",\n      \"tier\": 1,\n      \"besetzungsplatz\": 2,\n      \"minPlayers\": 2,\n      \"roleTitle\": \"Die Designstudentin\",\n      \"isPotentialKiller\": true,\n      \"colorCode\": \"#6B1D2F\",\n      \"farbname\": \"Beerenrot\",\n      \"startRoom\": \"thekensaal\",\n      \"ermittlungsOrt\": \"am_linken_buffet\",\n      \"coordinates\": {\n        \"x\": 13.5,\n        \"y\": 13.5\n      },\n      \"visualSpecs\": {\n        \"silhouette\": \"Schlanke Statur, taubengraues Kopftuch, knielanger Wollmantel\",\n        \"outfit\": \"Beerenroter Wollmantel, dunkler Rollkragen, schwarze Stoffhose, taubengraues Kopftuch\",\n        \"distinguishingFeature\": \"Schwere Umhängetasche aus Leder, breiter Silberring an der rechten Hand\",\n        \"idleAnimation\": \"Nestelt am Reißverschluss ihrer Tasche und lächelt Emine zu\"\n      },\n      \"motiveAndConflict\": \"Fatma schreibt ihre Abschlussarbeit über alte Münzbilder. Azra hat ihr von der Münzschatulle in der Schauvitrine erzählt. Um 23:40 hebt sie die gesprungene Scheibe an und nimmt die Schatulle mit. Sie will die Reliefs zu Hause abzeichnen und die Schatulle am Montag zurückbringen. Um 23:56 sieht Herr Schneider Glassplitter an ihrem Mantel: „Die Schatulle. Um Punkt zwölf geh ich raus und ruf die Polizei.“\",\n      \"blackoutAlibi\": \"Behauptet, die ganze Zeit beim Gebäck am linken Buffettisch gestanden zu haben.\",\n      \"roleSecret\": \"Nachdem Herr Schneider sie um 23:56 erwischt hat, will sie ihm die Schatulle sofort zurückgeben. Um 23:57 geht sie mit der Tasche zur Theken-Klappe.\",\n      \"persoenlichesZiel\": \"Die Schatulle soll zurück, ohne dass es alle erfahren.\",\n      \"nebendelikt\": {\n        \"id\": \"nd_schatulle\",\n        \"text\": \"Hat die Münzschatulle aus der Schauvitrine mitgenommen.\"\n      },\n      \"loyalitaet\": {\n        \"zu\": \"emine\",\n        \"grund\": \"Emine ist seit der Schulzeit ihre beste Freundin.\"\n      },\n      \"luegen\": [\n        {\n          \"id\": \"luege_fatma_buffet\",\n          \"behauptung\": \"Ich stand die ganze Zeit beim Gebäck am linken Buffet.\",\n          \"wahrheit\": \"Um 23:57 war sie mit der Tasche an der Theken-Klappe.\",\n          \"duWahrheit\": \"Um 23:57 warst du mit der Tasche an der Theken-Klappe.\"\n        },\n        {\n          \"id\": \"luege_fatma_tasche\",\n          \"behauptung\": \"In meiner Tasche sind nur Bücher.\",\n          \"wahrheit\": \"In der Tasche liegt die Münzschatulle aus der Vitrine.\",\n          \"duWahrheit\": \"In der Tasche liegt die Münzschatulle aus der Vitrine.\"\n        }\n      ],\n      \"innocentProfile\": {\n        \"actualBehavior\": \"Beim Knall zieht sie sich mit der Tasche zum linken Buffettisch zurück und kauert dort gleich danach neben Emine.\"\n      },\n      \"killerProfile\": {\n        \"crimeExecution\": \"Beim Knall bleibt sie erschrocken vor der Theke stehen. Dann sieht sie das Kerzenlicht an der Anrichte und geht durch die Klappe hin, um die Schatulle sofort zurückzugeben. Herr Schneider packt den Gurt ihrer Tasche und zischt: „Zu spät. Die Polizei kommt so oder so.“ In Panik greift sie den Kerzenständer und schlägt einmal zu. In Panik reißt sie den Bund vom Gürtel: Wer den Schlüssel hat, kommt raus, bevor das Licht angeht. Gleich danach merkt sie, dass Flucht alles schlimmer macht. Sie steckt ihn in die Brottasche auf dem linken Buffettisch und kauert sich zu Emine.\",\n        \"smokingGun\": \"Frischer Messingabrieb an ihrem breiten Silberring, passend zum Kerzenständer.\",\n        \"zusatzindiz\": \"Rote Wachstropfen auf der Münzschatulle in ihrer Tasche.\"\n      },\n      \"look\": {\n        \"haut\": \"#e6be9e\",\n        \"haar\": \"#2b1d14\",\n        \"kopf\": \"kopftuch\",\n        \"statur\": \"slim\",\n        \"schnitt\": \"dress\",\n        \"kopftuchFarbe\": \"#9A8C98\"\n      },\n      \"alltag\": \"Studiert Kommunikationsdesign im letzten Semester.\"\n    },\n    {\n      \"id\": \"olli\",\n      \"name\": \"Olli\",\n      \"vollerName\": \"Olliver\",\n      \"aussprache\": \"Olli\",\n      \"age\": 28,\n      \"geschlecht\": \"m\",\n      \"herkunft\": \"deutsch\",\n      \"tier\": 1,\n      \"besetzungsplatz\": 3,\n      \"minPlayers\": 3,\n      \"roleTitle\": \"Der Anpacker\",\n      \"isPotentialKiller\": true,\n      \"colorCode\": \"#1F3A52\",\n      \"farbname\": \"Marineblau und Khaki\",\n      \"startRoom\": \"ost_saal\",\n      \"ermittlungsOrt\": \"ost_tafel_kopf\",\n      \"coordinates\": {\n        \"x\": 22.5,\n        \"y\": 10.5\n      },\n      \"visualSpecs\": {\n        \"silhouette\": \"Breit gebaut, kräftige Schultern, leicht gebeugte Haltung\",\n        \"outfit\": \"Grauer Kapuzenpulli, dunkelblaue Daunenweste, Khakihose mit Seitentaschen\",\n        \"distinguishingFeature\": \"Holzsplitter und weißer Kalk an den Ärmeln des Pullis; der rechte Arbeitshandschuh hängt aus der Westentasche, der linke liegt seit 19:30 am Kamin\",\n        \"idleAnimation\": \"Reibt sich den Nacken, wechselt das Standbein und schaut auf seine Hände\"\n      },\n      \"motiveAndConflict\": \"Um 18:30 trägt Olli mit Wojtek die Warmhaltebehälter durch den Turm. Dabei schrammt er die geschnitzte Bogentür, ein Beschlag reißt aus. Herr Schneider verlangt 2.000 € Bargeld und schließt die Tore ab: „Keiner geht, bevor das bezahlt ist.“ Um 23:00 streiten die beiden laut.\",\n      \"blackoutAlibi\": \"Behauptet, die ganze Zeit am Kopf der Tafel im Ost-Saal gesessen zu haben.\",\n      \"roleSecret\": \"Um 23:57 holt er am Eiskübel Eis für Wojteks eingeklemmten Finger. Herr Schneider raunzt ihn an: „Zweitausend, bis zwölf.“\",\n      \"persoenlichesZiel\": \"Den Türschaden selbst mit Herrn Schneider klären, ohne die Gruppe hineinzuziehen.\",\n      \"nebendelikt\": {\n        \"id\": \"nd_tuerschaden\",\n        \"text\": \"Hat die Bogentür beschädigt und wollte die Schramme mit Möbelwachs verdecken.\"\n      },\n      \"loyalitaet\": {\n        \"zu\": \"kaan\",\n        \"grund\": \"Wojtek hat ihm beim Tragen geholfen und hält zu ihm.\"\n      },\n      \"luegen\": [\n        {\n          \"id\": \"luege_olli_tafel\",\n          \"behauptung\": \"Ich saß die ganze Zeit am Tisch im Ost-Saal.\",\n          \"wahrheit\": \"Um 23:57 war er am Eiskübel vor der Theke, danach kauerte er am rechten Buffettisch.\",\n          \"duWahrheit\": \"Um 23:57 warst du am Eiskübel vor der Theke. Danach hast du am rechten Buffettisch gekauert.\"\n        }\n      ],\n      \"innocentProfile\": {\n        \"actualBehavior\": \"Beim Knall tastet er sich vom Eiskübel zum rechten Buffettisch und kauert dort gleich danach neben Azra, bis das Licht angeht. Dann bringt er Wojtek das Eis und setzt sich in den Ost-Saal an die Tafel.\"\n      },\n      \"killerProfile\": {\n        \"crimeExecution\": \"Er bleibt erst am Eiskübel stehen. Dann geht er vor der Theke entlang und durch die Klappe zum Kerzenlicht, weil er mit Herrn Schneider reden will. Herr Schneider packt ihn am Ärmel und zischt: „Zweitausend. Sonst Polizei.“ In Panik greift Olli den Kerzenständer am Fuß und schlägt einmal zu. Rote Tropfen fallen auf den Handschuh, der aus seiner Westentasche hängt. In Panik reißt er den Bund vom Gürtel: Wer den Schlüssel hat, kommt raus, bevor das Licht angeht. Gleich danach merkt er, dass Flucht alles schlimmer macht. Er wirft ihn in den Eiskübel und kauert sich zu Azra.\",\n        \"smokingGun\": \"Holzsplitter und weißer Kalk von seinen Ärmeln kleben im Wachs am Fuß des Kerzenständers, das inzwischen erstarrt ist.\",\n        \"zusatzindiz\": \"Rote Kerzenwachstropfen auf dem Arbeitshandschuh in seiner Westentasche.\"\n      },\n      \"look\": {\n        \"haut\": \"#f1d3bc\",\n        \"haar\": \"#7a5638\",\n        \"kopf\": \"none\",\n        \"statur\": \"broad\",\n        \"schnitt\": \"suit\"\n      },\n      \"alltag\": \"Ist Lagerlogistiker und hilft bei jedem Umzug im Freundeskreis.\"\n    },\n    {\n      \"id\": \"can\",\n      \"name\": \"Can\",\n      \"aussprache\": \"Dschan\",\n      \"age\": 25,\n      \"geschlecht\": \"m\",\n      \"herkunft\": \"türkisch\",\n      \"tier\": 1,\n      \"besetzungsplatz\": 4,\n      \"minPlayers\": 4,\n      \"roleTitle\": \"Der Spaßvogel\",\n      \"isPotentialKiller\": true,\n      \"colorCode\": \"#F5C400\",\n      \"farbname\": \"Signalgelb\",\n      \"startRoom\": \"west_saal\",\n      \"ermittlungsOrt\": \"west_bank_west\",\n      \"coordinates\": {\n        \"x\": 1.5,\n        \"y\": 10.5\n      },\n      \"visualSpecs\": {\n        \"silhouette\": \"Jugendlich, schlank, federnder Gang\",\n        \"outfit\": \"Signalgelber weiter Kapuzenpulli, weite Jeans, bunte Turnschuhe\",\n        \"distinguishingFeature\": \"Auffällige gelbe Kapuze, linke Hand tief in der Bauchtasche des Pullis (dort steckt die Maske)\",\n        \"idleAnimation\": \"Zieht an den Kapuzenbändern und wippt auf den Zehenspitzen\"\n      },\n      \"motiveAndConflict\": \"Can hat am Nachmittag eine weiße Gespenstermaske mit Leuchtfarbe angemalt. Um 23:54 versteckt er sich damit im dunklen Vorratsraum. Um zwölf soll die blinde Kuh zur Torte kommen und sich erschrecken. Kurz vor zwölf knallt es, das Licht geht aus, und die Tür zum Vorratsraum quietscht auf. Can glaubt, die blinde Kuh wird schon gebracht, und springt mit „Buuuh!“ hervor. Er läuft Herrn Schneider in die Arme. Der packt ihn an der Kapuze und ruft: „Hab ich dich!“\",\n      \"blackoutAlibi\": \"Behauptet, auf der Toilette im Turm gewesen zu sein.\",\n      \"roleSecret\": \"Er hat mit der Leuchtmaske im Vorratsraum gewartet. Herr Schneider hat ihn an der Kapuze gepackt.\",\n      \"persoenlichesZiel\": \"Der Streich soll nicht herauskommen.\",\n      \"nebendelikt\": {\n        \"id\": \"nd_streich\",\n        \"text\": \"Hat sich mit der Leuchtmaske im Vorratsraum versteckt, um die blinde Kuh zu erschrecken.\"\n      },\n      \"loyalitaet\": {\n        \"zu\": \"zeynep\",\n        \"grund\": \"Zeynep hat für ihn Schmiere gestanden.\"\n      },\n      \"luegen\": [\n        {\n          \"id\": \"luege_can_toilette\",\n          \"behauptung\": \"Ich war die ganze Zeit auf der Toilette im Turm.\",\n          \"wahrheit\": \"Er war im Vorratsraum und ist erst nach dem Zusammenstoß in den Turm gerannt.\",\n          \"duWahrheit\": \"Du warst im Vorratsraum und bist erst nach dem Zusammenstoß in den Turm gerannt.\"\n        },\n        {\n          \"id\": \"luege_can_maske\",\n          \"behauptung\": \"Welche Maske? Ich hab keine Maske.\",\n          \"wahrheit\": \"Die Leuchtmaske steckt in der Bauchtasche seines Pullis.\",\n          \"duWahrheit\": \"Die Leuchtmaske steckt in der Bauchtasche deines Pullis.\"\n        }\n      ],\n      \"innocentProfile\": {\n        \"actualBehavior\": \"Er reißt sich los und rennt durch den Durchgang, noch bevor es scheppert. Die leuchtende Maske hält er in der Hand. Im Kaminsaal rennt er zur Bogentür, stopft die Maske in die Bauchtasche seines Pullis und versteckt sich oben auf der Toilette im Turm.\"\n      },\n      \"killerProfile\": {\n        \"crimeExecution\": \"Herr Schneider hält ihn an der Kapuze fest und zischt: „Jetzt kommt die Polizei.“ In Panik greift Can mit der Hand voller Leuchtfarbe den Kerzenständer von der Anrichte und schlägt einmal zu. Herr Schneider stürzt in den Vorratsraum. Can kniet sich neben ihn und reißt in Panik den Bund vom Gürtel: Wer den Schlüssel hat, kommt raus, bevor das Licht angeht. Gleich danach merkt er, dass Flucht alles schlimmer macht. Er rennt nach dem Scheppern durch den Durchgang und den Kaminsaal, stopft an der Bogentür die Maske in die Bauchtasche, steckt den Bund in den Helm der Ritterrüstung und versteckt sich auf der Toilette im Turm.\",\n        \"smokingGun\": \"Ein Abdruck einer ganzen Hand in grünlich-weißer Leuchtfarbe um den Griff des Kerzenständers.\",\n        \"zusatzindiz\": \"Rote Wachstropfen auf der Leuchtmaske.\"\n      },\n      \"look\": {\n        \"haut\": \"#d9a983\",\n        \"haar\": \"#1a1412\",\n        \"kopf\": \"none\",\n        \"statur\": \"slim\",\n        \"schnitt\": \"suit\"\n      },\n      \"beweisFarbe\": \"Gelbe Kapuzenfasern an Herrn Schneiders Hand (gelbe_fasern) müssen eindeutig Can zugeordnet werden können.\",\n      \"alltag\": \"Macht eine Ausbildung zum Mediengestalter und dreht lustige Kurzvideos.\"\n    },\n    {\n      \"id\": \"leyla\",\n      \"name\": \"Lejla\",\n      \"quelle\": {\n        \"name\": \"Leyla\",\n        \"nr\": 5\n      },\n      \"aussprache\": \"Leila\",\n      \"age\": 25,\n      \"geschlecht\": \"w\",\n      \"herkunft\": \"bosnisch\",\n      \"tier\": 2,\n      \"besetzungsplatz\": 5,\n      \"minPlayers\": 5,\n      \"roleTitle\": \"Die Apothekerin\",\n      \"isPotentialKiller\": false,\n      \"colorCode\": \"#178582\",\n      \"farbname\": \"Türkis\",\n      \"startRoom\": \"thekensaal\",\n      \"ermittlungsOrt\": \"hinter_theke_mitte\",\n      \"coordinates\": {\n        \"x\": 15.5,\n        \"y\": 8.5\n      },\n      \"visualSpecs\": {\n        \"silhouette\": \"Zierlich, Haare zu einem straffen Dutt gebunden\",\n        \"outfit\": \"Türkise Latzschürze über beigem Strickpulli, dunkle Leggings\",\n        \"distinguishingFeature\": \"Abrechnungsblock in der Schürzentasche, Holzlöffel in der Hand\",\n        \"idleAnimation\": \"Rückt Schüsseln gerade und rührt im Warmhaltebehälter\"\n      },\n      \"motiveAndConflict