handschuh_russ\",\n          \"stelle\": \"Innenfläche\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Ein linker Arbeitshandschuh, rußig vom Kamin.\",\n          \"rolle\": {\n            \"alle\": \"umgebung\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"handschuh_weste_olli\",\n      \"name\": \"Ollis rechter Arbeitshandschuh\",\n      \"beschreibung\": \"Der rechte Arbeitshandschuh hängt aus der Tasche von Ollis Daunenweste.\",\n      \"lage\": {\n        \"traeger\": \"olli\",\n        \"stelle\": \"hängt aus der Westentasche\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_weste_moebelwachs\",\n          \"stelle\": \"Fingerkuppen\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"In Ollis Westentasche steckt sein rechter Arbeitshandschuh. An den Fingerkuppen sind braunes Möbelwachs und weißer Kalk. Darauf angesprochen gibt Olli zu: Er hat um 18:35 den Beschlag der Bogentür ausgerissen und die Schramme mit Wojteks Möbelwachs zugerieben.\",\n          \"rolle\": {\n            \"alle\": \"nebendelikt\"\n          },\n          \"nebendelikt\": \"nd_tuerschaden\"\n        },\n        {\n          \"id\": \"spur_weste_kerzenwachs\",\n          \"stelle\": \"Handrücken\",\n          \"entstehtWenn\": {\n            \"kerzenstaenderGegriffenVon\": \"olli\"\n          },\n          \"zeigt\": \"Auf dem Handrücken des Handschuhs kleben frische rote Kerzenwachstropfen.\",\n          \"harmlos\": \"Auf dem Handrücken des Handschuhs ist Kalkstaub.\",\n          \"rolle\": {\n            \"olli\": \"zusatzindiz\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"moebelwachs_dose\",\n      \"name\": \"Dose mit braunem Möbelwachs\",\n      \"beschreibung\": \"Aus Wojteks Werkzeugtasche.\",\n      \"lage\": {\n        \"traeger\": \"kaan\",\n        \"stelle\": \"in Wojteks Werkzeugtasche\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_moebelwachs\",\n          \"stelle\": \"Deckel\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Halb leer, am Rand Holzstaub.\",\n          \"rolle\": {\n            \"alle\": \"nebendelikt\"\n          },\n          \"nebendelikt\": \"nd_moebelwachs\"\n        }\n      ]\n    },\n    {\n      \"id\": \"mehrfachsteckdose_tim\",\n      \"name\": \"Tims alte Mehrfachsteckdose\",\n      \"beschreibung\": \"Eine alte Steckdosenleiste, an der die Kaffeemaschine hängt.\",\n      \"lage\": {\n        \"ort\": \"hinter_theke_ost\",\n        \"stelle\": \"auf dem Boden hinter der Theke beim Kaffeeautomaten\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_steckdose_verschmort\",\n          \"stelle\": \"Stecker\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Ein Steckplatz ist schwarz verschmort. Hier kam der Kurzschluss her.\",\n          \"rolle\": {\n            \"alle\": \"ausgangslage\"\n          },\n          \"nebendelikt\": \"nd_kurzschluss\"\n        }\n      ]\n    },\n    {\n      \"id\": \"notlaterne\",\n      \"name\": \"Notlaterne\",\n      \"beschreibung\": \"Akkulaterne am Haken direkt hinter der Vorratsraumtür.\",\n      \"lage\": {\n        \"ort\": \"vorrat_innen\",\n        \"stelle\": \"am Haken neben der Tür\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_laterne_unberuehrt\",\n          \"stelle\": \"Haken\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Die Laterne hängt unberührt am Haken neben der Tür.\",\n          \"rolle\": {\n            \"alle\": \"umgebung\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"vitrine\",\n      \"name\": \"Schauvitrine im Turmgang\",\n      \"beschreibung\": \"Alte Vitrine mit Holzrahmen ohne Messing; seit 21:00 hat die Scheibe einen Sprung.\",\n      \"lage\": {\n        \"einrichtung\": \"vitrine\",\n        \"ort\": \"an_der_vitrine\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_vitrine_leer\",\n          \"stelle\": \"Samtbett\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Die gesprungene Scheibe ist angehoben, Scherben am Boden, das Samtbett der Münzschatulle ist leer.\",\n          \"rolle\": {\n            \"alle\": \"umgebung\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"glassplitter_mantel\",\n      \"name\": \"Glassplitter an Fatmas Mantel\",\n      \"beschreibung\": \"Winzige Glassplitter im Wollmantel.\",\n      \"lage\": {\n        \"traeger\": \"fatma\",\n        \"stelle\": \"am rechten Ärmel des beerenroten Mantels\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_mantel_glas\",\n          \"stelle\": \"Ärmel\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Feine Glassplitter, wie von der Vitrinenscheibe.\",\n          \"rolle\": {\n            \"alle\": \"nebendelikt\"\n          },\n          \"nebendelikt\": \"nd_schatulle\",\n          \"widerlegt\": [\n            \"luege_fatma_tasche\"\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"gelbe_fasern\",\n      \"name\": \"Gelbe Fasern\",\n      \"beschreibung\": \"Fasern zwischen Herrn Schneiders Fingern.\",\n      \"lage\": {\n        \"traeger\": \"schneider\",\n        \"stelle\": \"an der rechten Hand\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_fasern_kapuze\",\n          \"stelle\": \"rechte Hand\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Knallgelbe Fasern, wie von einer Kapuze.\",\n          \"rolle\": {\n            \"ahmet\": \"falsche_faehrte\",\n            \"fatma\": \"falsche_faehrte\",\n            \"olli\": \"falsche_faehrte\",\n            \"can\": \"ausgangslage\"\n          },\n          \"belastet\": [\n            \"can\"\n          ],\n          \"widerlegtDurch\": \"Herr Schneider hat Can im Dunkeln an der Kapuze gepackt, noch vor seiner Gedächtnislücke. Die Fasern zeigen den Griff, nicht den Schlag.\",\n          \"widerlegt\": [\n            \"luege_can_toilette\"\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"wachs_boden\",\n      \"name\": \"Rotes Wachs auf dem Boden\",\n      \"beschreibung\": \"Spritzer von rotem Kerzenwachs.\",\n      \"lage\": {\n        \"ort\": \"vor_vorratstuer\",\n        \"stelle\": \"auf dem Steinboden vor der Vorratsraumtür\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_wachs_boden\",\n          \"stelle\": \"Boden\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Rote Wachsspritzer rund um die Stelle, an der der Kerzenständer liegt.\",\n          \"rolle\": {\n            \"alle\": \"umgebung\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"foto_joanna\",\n      \"name\": \"Joannas Foto von 23:51\",\n      \"beschreibung\": \"Ein Foto auf Joannas Handy.\",\n      \"lage\": {\n        \"traeger\": \"johanna\",\n        \"stelle\": \"auf ihrem Handy\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_foto_streit\",\n          \"stelle\": \"Galerie\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"23:51: Herr Schneider und Ahmet streiten an der Theke, Ahmet hält einen dicken Umschlag.\",\n          \"rolle\": {\n            \"alle\": \"motiv\"\n          },\n          \"belastet\": [\n            \"ahmet\"\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"notizbuch_tugba\",\n      \"name\": \"Tugbas Notizbuch\",\n      \"beschreibung\": \"Goldenes Notizbuch mit dem Ablaufplan.\",\n      \"lage\": {\n        \"traeger\": \"tugba\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_notiz_fehlende\",\n          \"stelle\": \"Seite 23:57\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"„Fehlen für die Torte: Ahmet (Theke, Servietten), Fatma (Theke), Olli (Eis), Can (?).“ Darunter: „Emine und Azra (Buffet), Damir und Tim (Kaffee), Marek (Saft), Zeynep, Hana, Wojtek, Sibel (Kaminsaal), Serkan (Auto).“\",\n          \"rolle\": {\n            \"alle\": \"ueberblick\"\n          },\n          \"widerlegt\": [\n            \"luege_olli_tafel\",\n            \"luege_fatma_buffet\"\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"handykorb\",\n      \"name\": \"Handykorb\",\n      \"beschreibung\": \"Korb für die Handys auf der Tafel im Ost-Saal. Er steht seit 23:50 dort; ab 23:55 kommen alle Handys hinein.\",\n      \"lage\": {\n        \"ort\": \"am_handykorb\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_handykorb\",\n          \"stelle\": \"Korb\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Alle Handys liegen darin. Hinter den Mauern fehlt der Empfang.\",\n          \"rolle\": {\n            \"alle\": \"ausgangslage\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"torte\",\n      \"name\": \"Mitternachtstorte\",\n      \"beschreibung\": \"Die Torte auf dem Regal im kühlen Vorratsraum.\",\n      \"lage\": {\n        \"ort\": \"vorrat_mitte\"\n      },\n      \"sichtbar\": true,\n      \"spuren\": [\n        {\n          \"id\": \"spur_torte\",\n          \"stelle\": \"Regal\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Unversehrt. Wenigstens etwas.\",\n          \"rolle\": {\n            \"alle\": \"umgebung\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"stirnlampe_tim\",\n      \"name\": \"Tims Stirnlampe\",\n      \"beschreibung\": \"Kleine Stirnlampe an einem Band um den Hals. Beim Tasten nach dem Hauptschalter rutschte sie ihm vom Hals; um 23:59:40 fand er sie auf dem Boden.\",\n      \"lage\": {\n        \"traeger\": \"tim\",\n        \"stelle\": \"um den Hals\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_stirnlampe\",\n          \"stelle\": \"Lampe\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Funktioniert. Damit hat Tim um Mitternacht den Sicherungskasten gefunden.\",\n          \"rolle\": {\n            \"alle\": \"ausgangslage\"\n          }\n        }\n      ]\n    },\n    {\n      \"id\": \"mietgeld\",\n      \"name\": \"Bündel mit dem Mietgeld\",\n      \"beschreibung\": \"Neunzehnmal 150 €, zusammen 2.850 €.\",\n      \"lage\": {\n        \"traeger\": \"ahmet\",\n        \"stelle\": \"in Ahmets Hosentasche, seit 0:12\"\n      },\n      \"sichtbar\": false,\n      \"spuren\": [\n        {\n          \"id\": \"spur_mietgeld\",\n          \"stelle\": \"Hosentasche\",\n          \"entstehtWenn\": {\n            \"immer\": true\n          },\n          \"zeigt\": \"Ein dickes Bündel Scheine, 2.850 €. Ahmet hat alles davon aufbewahrt.\",\n          \"rolle\": {\n            \"alle\": \"nebendelikt\"\n          },\n          \"nebendelikt\": \"nd_mietgeld\",\n          \"widerlegt\": [\n            \"luege_ahmet_miete\"\n          ]\n        }\n      ]\n    }\n  ],\n  \"nebendelikte\": [\n    {\n      \"id\": \"nd_mietgeld\",\n      \"person\": \"ahmet\",\n      \"text\": \"150 € Miete von allen kassiert, obwohl der Keller nichts gekostet hat.\",\n      \"duText\": \"Du hast von allen 150 € Miete kassiert, obwohl der Keller nichts gekostet hat.\"\n    },\n    {\n      \"id\": \"nd_schatulle\",\n      \"person\": \"fatma\",\n      \"text\": \"Münzschatulle aus der Schauvitrine mitgenommen.\",\n      \"duText\": \"Du hast die Münzschatulle aus der Schauvitrine mitgenommen.\"\n    },\n    {\n      \"id\": \"nd_tuerschaden\",\n      \"person\": \"olli\",\n      \"text\": \"Bogentür beschädigt und die Schramme mit Möbelwachs verdeckt.\",\n      \"duText\": \"Du hast die Bogentür beschädigt und die Schramme mit Möbelwachs verdeckt.\"\n    },\n    {\n      \"id\": \"nd_streich\",\n      \"person\": \"can\",\n      \"text\": \"Mit der Leuchtmaske im Vorratsraum versteckt.\",\n      \"duText\": \"Du hast dich mit der Leuchtmaske im Vorratsraum versteckt.\"\n    },\n    {\n      \"id\": \"nd_kurzschluss\",\n      \"person\": \"tim\",\n      \"text\": \"Trotz Warnung die alte Mehrfachsteckdose benutzt.\",\n      \"duText\": \"Du hast trotz Warnung die alte Mehrfachsteckdose benutzt.\"\n    },\n    {\n      \"id\": \"nd_parken\",\n      \"person\": \"murat\",\n      \"text\": \"Auf Herrn Schneiders reserviertem Platz geparkt.\",\n      \"duText\": \"Du hast auf Herrn Schneiders reserviertem Platz geparkt.\"\n    },\n    {\n      \"id\": \"nd_schmiere\",\n      \"person\": \"zeynep\",\n      \"text\": \"Für Cans Streich Schmiere gestanden.\",\n      \"duText\": \"Du hast für Cans Streich Schmiere gestanden.\"\n    },\n    {\n      \"id\": \"nd_moebelwachs\",\n      \"person\": \"kaan\",\n      \"text\": \"Olli das Möbelwachs zum Verdecken der Schramme gegeben.\",\n      \"duText\": \"Du hast Olli das Möbelwachs gegeben, damit er die Schramme verdecken kann.\"\n    }\n  ]\n}\n",
  "zeitleiste.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Gemeinsame Zeitleiste vom Eintreffen der Gäste bis zum Morgen. Sie ist in allen Pfaden gleich; was im Fenster 23:58–0:00 je Pfad anders ist, steht in den Tatmatrix-Dateien.\",\n  \"eintraege\": [\n    {\n      \"id\": \"z_ankunft\",\n      \"zeit\": \"18:00\",\n      \"ort\": \"im_windfang\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Die Gäste kommen über die fünf Sandsteinstufen und das Außentor in den Keller. Herr Schneider begrüßt alle knapp und zeigt den Weg.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_lieferung\",\n      \"zeit\": \"18:30\",\n      \"ort\": \"an_der_ruestung\",\n      \"wer\": [\n        \"murat\",\n        \"olli\",\n        \"kaan\"\n      ],\n      \"text\": \"Marek liefert das Essen über den Schlosshof und parkt auf Herrn Schneiders reserviertem Platz. Olli und Wojtek tragen die Warmhaltebehälter durch Hoftür, Turmgang und Bogentür.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_tuerschaden\",\n      \"zeit\": \"18:35\",\n      \"ort\": \"vor_bogentuer\",\n      \"wer\": [\n        \"olli\",\n        \"kaan\"\n      ],\n      \"text\": \"Olli schrammt mit einem Warmhaltebehälter die geschnitzte Bogentür. Ein Beschlag reißt aus, Holzsplitter und weißer Kalk bleiben an seinen Pulli-Ärmeln.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-07\"\n    },\n    {\n      \"id\": \"z_moebelwachs\",\n      \"zeit\": \"18:45\",\n      \"ort\": \"vor_bogentuer\",\n      \"wer\": [\n        \"olli\",\n        \"kaan\"\n      ],\n      \"text\": \"Wojtek gibt Olli braunes Möbelwachs aus seiner Werkzeugtasche. Olli reibt es mit seinem rechten Arbeitshandschuh in die Schramme und steckt den Handschuh in die Westentasche.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-16\"\n    },\n    {\n      \"id\": \"z_forderung\",\n      \"zeit\": \"18:50\",\n      \"ort\": \"vor_bogentuer\",\n      \"wer\": [\n        \"schneider\",\n        \"olli\"\n      ],\n      \"text\": \"Herr Schneider entdeckt den Schaden, verlangt 2.000 € Bargeld und schreibt es in seinen Quittungsblock. Er schließt Hoftür, Einfahrtstor und Außentor ab: „Keiner geht, bevor das bezahlt ist.“\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-02\"\n    },\n    {\n      \"id\": \"z_buffet\",\n      \"zeit\": \"19:00\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Das Buffet ist eröffnet: warmes Essen, Brot, Dips, Gebäck. Dazu schwarzer Tee aus dem großen Teekocher, Kaffee, alkoholfreier Apfelpunsch, Wasser und Säfte.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-14\"\n    },\n    {\n      \"id\": \"z_handschuh\",\n      \"zeit\": \"19:30\",\n      \"ort\": \"am_kamin\",\n      \"wer\": [\n        \"olli\"\n      ],\n      \"text\": \"Olli wärmt sich am noch kalten Kamin die Hände und vergisst dort seinen linken Arbeitshandschuh.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_verlaufen\",\n      \"zeit\": \"20:15\",\n      \"ort\": \"vorrat_mitte\",\n      \"wer\": [\n        \"olli\"\n      ],\n      \"text\": \"Lacher: Olli sucht die Toilette, nimmt die falsche Tür hinter der Theke und steht im dunklen Vorratsraum vor der Mitternachtstorte. „Ich wollte nur aufs Klo!“\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-17\"\n    },\n    {\n      \"id\": \"z_ruestung\",\n      \"zeit\": \"21:00\",\n      \"ort\": \"an_der_ruestung\",\n      \"wer\": [\n        \"selin\"\n      ],\n      \"text\": \"Lacher: Sibel hält die Ritterrüstung für einen Menschen, schreit auf und stolpert gegen die Schauvitrine. Die Scheibe bekommt einen feinen Sprung.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_kerzen\",\n      \"zeit\": \"22:00\",\n      \"ort\": \"an_anrichte\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Herr Schneider zündet die drei roten Kerzen im Messingkerzenständer auf der Anrichte an. Es sind die einzigen echten Kerzen im Keller.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-04\"\n    },\n    {\n      \"id\": \"z_musik\",\n      \"zeit\": \"22:00\",\n      \"ort\": \"ost_bank\",\n      \"wer\": [\n        \"schneider\",\n        \"baran\"\n      ],\n      \"text\": \"Herr Schneider verlangt leise Musik und droht, Barans Box einzukassieren.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_quittung\",\n      \"zeit\": \"22:30\",\n      \"ort\": \"ost_tafel_west\",\n      \"wer\": [\n        \"aylin\",\n        \"schneider\"\n      ],\n      \"text\": \"Aylin fragt Herrn Schneider nach einem Beleg für die Miete. Er schreibt ihr auf einen Quittungszettel: „Miete: 0 Euro.“\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_streit_olli\",\n      \"zeit\": \"23:00\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"schneider\",\n        \"olli\",\n        \"hakan\"\n      ],\n      \"text\": \"Lauter Streit zwischen Herrn Schneider und Olli um die 2.000 €. Pawel versucht zu schlichten und wird barsch abgewiesen.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_kamin\",\n      \"zeit\": \"23:20\",\n      \"ort\": \"am_kamin\",\n      \"wer\": [\n        \"meryem\"\n      ],\n      \"text\": \"Hana feuert den Kamin an, ohne die Kaminklappe zu öffnen.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_qualm\",\n      \"zeit\": \"23:30\",\n      \"ort\": \"am_kamin\",\n      \"wer\": [\n        \"meryem\",\n        \"schneider\"\n      ],\n      \"text\": \"Lacher: Dichter Qualm füllt den Kaminsaal, alle husten. Die Klappen der Lichtschächte werden aufgerissen, das Feuer wird gelöscht. Seitdem zieht Luft vom Buffetsaal in den Kaminsaal.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-17\"\n    },\n    {\n      \"id\": \"z_vitrine_schatulle\",\n      \"zeit\": \"23:40\",\n      \"ort\": \"an_der_vitrine\",\n      \"wer\": [\n        \"fatma\",\n        \"emine\"\n      ],\n      \"text\": \"Fatma hebt die gesprungene Scheibe der Vitrine an und nimmt die Münzschatulle mit. Emine sieht es.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-08\"\n    },\n    {\n      \"id\": \"z_tasche_ausgebeult\",\n      \"zeit\": \"23:45\",\n      \"ort\": \"am_linken_buffet\",\n      \"wer\": [\n        \"dilara\",\n        \"fatma\"\n      ],\n      \"text\": \"Azra sieht, dass Fatmas Tasche auffällig ausgebeult ist.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_finger\",\n      \"zeit\": \"23:50\",\n      \"ort\": \"vor_bogentuer\",\n      \"wer\": [\n        \"kaan\"\n      ],\n      \"text\": \"Wojtek klemmt sich an der Bogentür den Finger ein.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_foto_streit\",\n      \"zeit\": \"23:51\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"schneider\",\n        \"ahmet\",\n        \"johanna\"\n      ],\n      \"text\": \"Herr Schneider zu Ahmet an der Theke: „Um zwölf sag ich allen, was der Keller gekostet hat.“ Joanna fotografiert den Streit.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_olli_eis\",\n      \"zeit\": \"23:52\",\n      \"ort\": \"vor_bogentuer\",\n      \"wer\": [\n        \"olli\",\n        \"kaan\"\n      ],\n      \"text\": \"Olli zu Wojtek: „Ich hol dir Eis. Und dann red ich mit Schneider.“\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_vitrine_offen\",\n      \"zeit\": \"23:53\",\n      \"ort\": \"an_der_vitrine\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Herr Schneider entdeckt auf seiner Runde die offene Vitrine und die Scherben.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_can_vorrat\",\n      \"zeit\": \"23:54\",\n      \"ort\": \"vorrat_mitte\",\n      \"wer\": [\n        \"can\",\n        \"zeynep\"\n      ],\n      \"text\": \"Can schleicht über den Durchgang hinter die Theke in den Vorratsraum, macht dort das Licht aus und wartet mit der Leuchtmaske auf die blinde Kuh. Zeynep steht am Bogen zum Durchgang Schmiere.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-05\"\n    },\n    {\n      \"id\": \"z_tortenplan\",\n      \"zeit\": \"23:55\",\n      \"ort\": \"an_der_wandtafel\",\n      \"wer\": [\n        \"tugba\",\n        \"detective\",\n        \"baran\"\n      ],\n      \"text\": \"Tugba ruft alle zu ihrem Mitternachtsspiel „Blinde Kuh“ in den Ost-Saal, die Handys kommen in den Handykorb. Der Detektiv bekommt als blinde Kuh eine Augenbinde und Barans Kopfhörer mit lauter Musik. Um zwölf soll die blinde Kuh zur Torte in den Vorratsraum geführt werden.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-05\"\n    },\n    {\n      \"id\": \"z_jacke\",\n      \"zeit\": \"23:55\",\n      \"ort\": \"am_jackenstaender\",\n      \"wer\": [\n        \"ahmet\"\n      ],\n      \"text\": \"Ahmet hängt seine schwarze Jacke an den Jackenständer im Ost-Saal.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"V-03\"\n    },\n    {\n      \"id\": \"z_serkan_tor\",\n      \"zeit\": \"23:56\",\n      \"ort\": \"am_aussentor\",\n      \"wer\": [\n        \"serkan\"\n      ],\n      \"text\": \"Serkan will Decken aus dem Auto holen und findet das Außentor verschlossen.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-03\"\n    },\n    {\n      \"id\": \"z_schatulle_entdeckt\",\n      \"zeit\": \"23:56\",\n      \"ort\": \"am_linken_buffet\",\n      \"wer\": [\n        \"schneider\",\n        \"fatma\",\n        \"emine\"\n      ],\n      \"text\": \"Herr Schneider sieht Glassplitter an Fatmas Mantel: „Die Schatulle. Um Punkt zwölf geh ich raus und ruf die Polizei.“\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-08\"\n    },\n    {\n      \"id\": \"z_theke_2357\",\n      \"zeit\": \"23:57\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"ahmet\",\n        \"fatma\",\n        \"olli\",\n        \"schneider\",\n        \"enes\",\n        \"leyla\"\n      ],\n      \"text\": \"Fatma geht mit der Tasche zur Theken-Klappe, Olli holt am Eiskübel Eis, Ahmet schlüpft mit dem Umschlag hinter die Theke. Herr Schneider raunzt Olli an: „Zweitausend, bis zwölf.“\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_steckdose\",\n      \"zeit\": \"23:57:50\",\n      \"ort\": \"hinter_theke_ost\",\n      \"wer\": [\n        \"tim\",\n        \"schneider\"\n      ],\n      \"text\": \"Herr Schneider warnt Tim vor der alten Leiste. Tim steckt die Kaffeemaschine trotzdem in seine Mehrfachsteckdose.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"V-06\"\n    },\n    {\n      \"id\": \"z_ausfall\",\n      \"zeit\": \"23:58\",\n      \"ort\": \"hinter_theke_ost\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Knall. Die Hauptsicherung fliegt raus, überall ist es dunkel. Nur die Kerzen an der Anrichte und das grüne Notausgangsschild leuchten.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-04\"\n    },\n    {\n      \"id\": \"z_zusammenstoss\",\n      \"zeit\": \"23:58:13\",\n      \"ort\": \"vor_vorratstuer\",\n      \"wer\": [\n        \"schneider\",\n        \"can\"\n      ],\n      \"text\": \"Herr Schneider will die Notlaterne holen. Can springt mit der leuchtenden Maske aus dem Vorratsraum, Herr Schneider packt ihn an der Kapuze: „Hab ich dich!“\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-05\"\n    },\n    {\n      \"id\": \"z_schlag\",\n      \"zeit\": \"23:58:40\",\n      \"ort\": \"vor_vorratstuer\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Ein dumpfer Schlag, Poltern, Metall scheppert über den Steinboden. Die Kerzen erlöschen. Herr Schneider stürzt in den Vorratsraum. Wer zugeschlagen hat, steht in der Tatmatrix des jeweiligen Pfads.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-05\"\n    },\n    {\n      \"id\": \"z_bund_weg\",\n      \"zeit\": \"23:58:45\",\n      \"ort\": \"vorrat_innen\",\n      \"wer\": [],\n      \"text\": \"Der Schlüsselbund wird vom Gürtel gezogen. Wer ihn nimmt und wo er landet, steht in der Tatmatrix des jeweiligen Pfads.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"B-02\"\n    },\n    {\n      \"id\": \"z_licht\",\n      \"zeit\": \"00:00\",\n      \"ort\": \"am_sicherungskasten\",\n      \"wer\": [\n        \"tim\"\n      ],\n      \"text\": \"Tim schaltet die Hauptsicherung wieder ein.\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"V-06\"\n    },\n    {\n      \"id\": \"z_gefunden\",\n      \"zeit\": \"00:00:20\",\n      \"ort\": \"vorrat_innen\",\n      \"wer\": [\n        \"enes\",\n        \"schneider\"\n      ],\n      \"text\": \"Damir findet Herrn Schneider im Vorratsraum.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_wach\",\n      \"zeit\": \"00:01:30\",\n      \"ort\": \"vorrat_innen\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Herr Schneider kommt zu sich: Beule, Gedächtnislücke. „Mein Schlüsselbund! Der ist weg!“\",\n      \"pfade\": \"alle\",\n      \"quelle\": \"V-05\"\n    },\n    {\n      \"id\": \"z_festgesetzt\",\n      \"zeit\": \"00:03\",\n      \"ort\": \"unter_notausgang\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Das Außentor ist zu, der Bund ist weg, hinter den Mauern gibt es keinen Empfang. Die Gruppe sitzt bis zum Morgen fest.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_handys\",\n      \"zeit\": \"00:05\",\n      \"ort\": \"am_handykorb\",\n      \"wer\": [\n        \"tugba\"\n      ],\n      \"text\": \"Tugba gibt die Handys aus dem Korb zurück. Empfang hat keines.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_umschlag\",\n      \"zeit\": \"00:12\",\n      \"ort\": \"am_kamin\",\n      \"wer\": [\n        \"ahmet\"\n      ],\n      \"text\": \"Ahmet leert den Umschlag mit dem Mietgeld und wirft ihn in den Ascheneimer am Kamin. Hana sieht es.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_ersatzschluessel\",\n      \"zeit\": \"00:15\",\n      \"ort\": \"wendeltreppe_fuss\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Herrn Schneider fällt der Ersatzschlüssel der Stiftung ein. Er holt ihn aus dem Schlüsselkasten im Turmgang und schließt damit die Hoftür, den Turm und die Seitentür vom Schlosshof ins Erdgeschoss auf. Das Außentor und das Einfahrtstor des Hofs öffnet der Ersatzschlüssel nicht. Hof und Garten sind hoch ummauert, die Fenster im Erdgeschoss vergittert. Die Gruppe sitzt weiter bis zum Morgen fest.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_auftrag\",\n      \"zeit\": \"00:20\",\n      \"ort\": \"hinter_rechtem_buffet\",\n      \"wer\": [\n        \"schneider\",\n        \"detective\"\n      ],\n      \"text\": \"Herr Schneider bittet den Detektiv: „Finde raus, wer das war. Bis zum Morgen.“\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_runde1\",\n      \"zeit\": \"00:30\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Runde 1: Das Alibi-Geflecht.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_runde2\",\n      \"zeit\": \"01:15\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Runde 2: Die Indizien-Filterung.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_runde3\",\n      \"zeit\": \"02:00\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Runde 3: Die finale Gegenüberstellung.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_finale\",\n      \"zeit\": \"02:45\",\n      \"ort\": \"vor_theke\",\n      \"wer\": [\n        \"alle\"\n      ],\n      \"text\": \"Finale: die Anklage.\",\n      \"pfade\": \"alle\"\n    },\n    {\n      \"id\": \"z_morgen\",\n      \"zeit\": \"07:00\",\n      \"ort\": \"im_windfang\",\n      \"wer\": [\n        \"schneider\"\n      ],\n      \"text\": \"Herrn Schneiders Kollegin kommt mit ihrem Torschlüssel und schließt das Außentor auf.\",\n      \"pfade\": \"alle\"\n    }\n  ]\n}\n",
  "beobachtungen.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Beobachtungen der Zeugen. Jede Beobachtung ist aus der Tatmatrix ableitbar (beleg). Kanal: pflichtgespraech = darf am Tisch erzählt werden (nur pfadneutral, Regel P-1); verborgen = steht im Dossier unter „Was ich verberge“ und erreicht den Detektiv nur über eine Entscheidung oder den Bonus-Hinweis; erzaehler = kommt über den Erzähler. Ein Trenner unterscheidet den Pfad einer Kernperson; jeder hat genau einen Zeugen.\",\n  \"beobachtungen\": [\n    {\n      \"id\": \"b_lejla_ahmet_theke\",\n      \"wer\": \"leyla\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Um 23:57 schlüpfte Ahmet mit einem dicken Umschlag hinter die Theke.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"ahmet\",\n            \"detail\": [\n              \"erkannt\"\n            ],\n            \"von\": \"23:56:50\",\n            \"bis\": \"23:57:10\"\n          }\n        ]\n      },\n      \"widerlegt\": [\n        \"luege_ahmet_servietten\"\n      ],\n      \"belastet\": [\n        \"ahmet\"\n      ]\n    },\n    {\n      \"id\": \"b_damir_an_der_theke\",\n      \"wer\": \"enes\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Um 23:57 standen Ahmet, Fatma und Olli an der Theke, Herr Schneider am Ostende. Can war nicht zu sehen.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"ahmet\",\n            \"detail\": [\n              \"erkannt\"\n            ],\n            \"von\": \"23:57:00\",\n            \"bis\": \"23:57:20\"\n          },\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"fatma\",\n            \"detail\": [\n              \"erkannt\"\n            ],\n            \"von\": \"23:57:00\",\n            \"bis\": \"23:57:20\"\n          },\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"olli\",\n            \"detail\": [\n              \"erkannt\"\n            ],\n            \"von\": \"23:57:00\",\n            \"bis\": \"23:57:20\"\n          },\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"schneider\",\n            \"detail\": [\n              \"erkannt\"\n            ],\n            \"von\": \"23:57:00\",\n            \"bis\": \"23:57:20\"\n          }\n        ],\n        \"keine\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"von\": \"23:57:00\",\n            \"bis\": \"23:57:20\"\n          }\n        ]\n      },\n      \"widerlegt\": [\n        \"luege_fatma_buffet\",\n        \"luege_olli_tafel\"\n      ],\n      \"belastet\": [\n        \"ahmet\",\n        \"fatma\",\n        \"olli\"\n      ]\n    },\n    {\n      \"id\": \"b_emine_schatulle\",\n      \"wer\": \"emine\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Um 23:40 sah sie im Turmgang, wie Fatma die Münzschatulle aus der Vitrine nahm.\",\n      \"duText\": \"Um 23:40 hast du im Turmgang gesehen, wie Fatma die Münzschatulle aus der Vitrine nahm.\",\n      \"beleg\": {\n        \"zeitleiste\": [\n          \"z_vitrine_schatulle\"\n        ]\n      },\n      \"widerlegt\": [\n        \"luege_fatma_tasche\"\n      ],\n      \"belastet\": [\n        \"fatma\"\n      ],\n      \"grundVerborgen\": \"Sie hat Fatma versprochen zu schweigen, weil Fatma die Schatulle am Montag zurückbringen will.\"\n    },\n    {\n      \"id\": \"b_emine_versteck\",\n      \"wer\": \"emine\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Beim Knall duckte sie sich hinter den linken Buffettisch und blieb dort, bis das Licht anging.\",\n      \"duText\": \"Beim Knall hast du dich hinter den linken Buffettisch geduckt und bist dort geblieben, bis das Licht anging.\",\n      \"beleg\": {\n        \"aufenthalt\": {\n          \"person\": \"emine\",\n          \"ort\": \"hinter_linkem_buffet\",\n          \"von\": \"23:58:00\",\n          \"bis\": \"00:00:00\"\n        }\n      }\n    },\n    {\n      \"id\": \"b_azra_tasche\",\n      \"wer\": \"dilara\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Um 23:45 war Fatmas Tasche auffällig ausgebeult.\",\n      \"beleg\": {\n        \"zeitleiste\": [\n          \"z_tasche_ausgebeult\"\n        ]\n      },\n      \"belastet\": [\n        \"fatma\"\n      ]\n    },\n    {\n      \"id\": \"b_azra_versteck\",\n      \"wer\": \"dilara\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Beim Knall duckte sie sich am rechten Buffettisch und blieb dort, bis das Licht anging.\",\n      \"duText\": \"Beim Knall hast du dich am rechten Buffettisch geduckt und bist dort geblieben, bis das Licht anging.\",\n      \"beleg\": {\n        \"aufenthalt\": {\n          \"person\": \"dilara\",\n          \"ort\": \"am_rechten_buffet\",\n          \"von\": \"23:58:00\",\n          \"bis\": \"00:00:00\"\n        }\n      }\n    },\n    {\n      \"id\": \"b_joanna_foto\",\n      \"wer\": \"johanna\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Sie hat ein Foto von 23:51: Herr Schneider und Ahmet streiten an der Theke, Ahmet hält einen dicken Umschlag.\",\n      \"duText\": \"Du hast ein Foto von 23:51: Herr Schneider und Ahmet streiten an der Theke, Ahmet hält einen dicken Umschlag.\",\n      \"beleg\": {\n        \"gegenstand\": [\n          \"foto_joanna\"\n        ],\n        \"zeitleiste\": [\n          \"z_foto_streit\"\n        ]\n      },\n      \"belastet\": [\n        \"ahmet\"\n      ],\n      \"grundVerborgen\": \"Ahmet hat sie gebeten, das Foto zu löschen.\"\n    },\n    {\n      \"id\": \"b_marek_gesicht\",\n      \"wer\": \"murat\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Im Dunkeln rannte ein leuchtendes Gespenstergesicht an ihm vorbei durch den Durchgang Richtung Kaminsaal.\",\n      \"duText\": \"Im Dunkeln rannte ein leuchtendes Gespenstergesicht an dir vorbei durch den Durchgang Richtung Kaminsaal.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:00\",\n            \"bis\": \"23:59:30\"\n          }\n        ]\n      },\n      \"belastet\": [\n        \"can\"\n      ]\n    },\n    {\n      \"id\": \"b_selin_gesicht\",\n      \"wer\": \"selin\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Im Dunkeln huschte ein leuchtendes Gesicht quer durch den Kaminsaal zur Bogentür.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:00\",\n            \"bis\": \"23:59:30\"\n          }\n        ]\n      },\n      \"belastet\": [\n        \"can\"\n      ]\n    },\n    {\n      \"id\": \"b_tim_gesicht\",\n      \"wer\": \"tim\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Am Sicherungskasten huschte im Dunkeln ein leuchtendes Gesicht an ihm vorbei.\",\n      \"duText\": \"Am Sicherungskasten huschte im Dunkeln ein leuchtendes Gesicht an dir vorbei.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:00\",\n            \"bis\": \"23:59:30\"\n          }\n        ]\n      },\n      \"belastet\": [\n        \"can\"\n      ]\n    },\n    {\n      \"id\": \"b_tim_kurzschluss\",\n      \"wer\": \"tim\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Der Kurzschluss kam von seiner alten Mehrfachsteckdose.\",\n      \"duText\": \"Der Kurzschluss kam von deiner alten Mehrfachsteckdose.\",\n      \"beleg\": {\n        \"ereignis\": [\n          \"ev_tim_steckdose\",\n          \"ev_knall\"\n        ],\n        \"gegenstand\": [\n          \"mehrfachsteckdose_tim\"\n        ]\n      },\n      \"grundVerborgen\": \"Er schämt sich, weil Herr Schneider ihn gewarnt hatte.\"\n    },\n    {\n      \"id\": \"b_zeynep_vorrat\",\n      \"wer\": \"zeynep\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Can hat mit der Leuchtmaske im dunklen Vorratsraum auf die blinde Kuh gewartet.\",\n      \"beleg\": {\n        \"zeitleiste\": [\n          \"z_can_vorrat\"\n        ]\n      },\n      \"widerlegt\": [\n        \"luege_can_toilette\",\n        \"luege_can_maske\"\n      ],\n      \"belastet\": [\n        \"can\"\n      ],\n      \"grundVerborgen\": \"Can ist ihr Bruder.\"\n    },\n    {\n      \"id\": \"b_zeynep_gesicht\",\n      \"wer\": \"zeynep\",\n      \"pfade\": \"alle\",\n      \"art\": \"pfadneutral\",\n      \"kanal\": \"pflichtgespraech\",\n      \"text\": \"Ein leuchtendes Gesicht kam aus dem Durchgang an ihr vorbei in den Kaminsaal.\",\n      \"duText\": \"Ein leuchtendes Gesicht kam aus dem Durchgang an dir vorbei in den Kaminsaal.\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:0