 [\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"sagt:ahmet\",\n            \"detail\": [\n              \"sprecher\"\n            ],\n            \"von\": \"23:58:03\",\n            \"bis\": \"23:58:03\"\n          },\n          {\n            \"sinn\": \"fuehlen\",\n            \"quelle\": \"ahmet\",\n            \"umfasst\": \"23:58:40\"\n          }\n        ]\n      },\n      \"entlastet\": [\n        \"ahmet\"\n      ],\n      \"trenner\": \"ahmet\",\n      \"grundVerborgen\": \"Er will nicht, dass sein Ärger mit Herrn Schneider zur Sprache kommt.\"\n    },\n    {\n      \"id\": \"b_damir_ahmet_weg\",\n      \"wer\": \"enes\",\n      \"pfade\": [\n        \"ahmet\",\n        \"can\"\n      ],\n      \"art\": \"pfadabhaengig\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Beim Scheppern war Ahmet nicht neben ihm. Er war kurz davor aufgestanden und kam erst danach zurück: „Damir, ich bin's wieder.“\",\n      \"duText\": \"Beim Scheppern war Ahmet nicht neben dir. Er war kurz davor aufgestanden und kam erst danach zurück: „Damir, ich bin's wieder.“\",\n      \"beleg\": {\n        \"alle\": [\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"sagt:ahmet\",\n            \"detail\": [\n              \"sprecher\"\n            ],\n            \"von\": \"23:58:03\",\n            \"bis\": \"23:58:03\"\n          }\n        ],\n        \"keine\": [\n          {\n            \"sinn\": \"fuehlen\",\n            \"quelle\": \"ahmet\",\n            \"umfasst\": \"23:58:40\"\n          }\n        ],\n        \"reihenfolge\": [\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"ev_scheppern\"\n          },\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"sagt:ahmet\",\n            \"detail\": [\n              \"sprecher\"\n            ],\n            \"von\": \"23:58:41\",\n            \"bis\": \"00:00:00\"\n          }\n        ]\n      },\n      \"belastet\": [\n        \"ahmet\"\n      ],\n      \"trenner\": \"ahmet\",\n      \"grundVerborgen\": \"Ahmet ist ein Freund; er will ihn nicht ohne Not belasten.\"\n    },\n    {\n      \"id\": \"b_ahmet_haelt\",\n      \"wer\": \"ahmet\",\n      \"pfade\": [\n        \"fatma\",\n        \"olli\"\n      ],\n      \"art\": \"pfadabhaengig\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Im Dunkeln blieb er neben Damir und hielt den Umschlag mit dem Mietgeld fest, bis das Licht anging.\",\n      \"duText\": \"Im Dunkeln bleibst du neben Damir und hältst den Umschlag mit dem Mietgeld fest, bis das Licht angeht.\",\n      \"beleg\": {\n        \"aufenthalt\": {\n          \"person\": \"ahmet\",\n          \"ort\": \"hinter_theke_ost\",\n          \"von\": \"23:58:00\",\n          \"bis\": \"00:00:00\"\n        }\n      },\n      \"grundVerborgen\": \"Sonst fragt jemand, was in dem Umschlag ist.\"\n    },\n    {\n      \"id\": \"b_ahmet_jacke\",\n      \"wer\": \"ahmet\",\n      \"pfade\": [\n        \"can\"\n      ],\n      \"art\": \"pfadabhaengig\",\n      \"kanal\": \"verborgen\",\n      \"eigenwissen\": true,\n      \"text\": \"Kurz vor dem Scheppern stand er auf und ging im Dunkeln in den Ost-Saal. Dort steckte er den Umschlag in seine Jacke. Erst nach dem Scheppern kam er zurück zu Damir. Kurz nach zwölf holte er den Umschlag wieder aus der Jacke.\",\n      \"duText\": \"Kurz vor dem Scheppern stehst du auf und gehst im Dunkeln in den Ost-Saal. Dort steckst du den Umschlag in deine Jacke. Erst nach dem Scheppern kommst du zurück zu Damir. Kurz nach zwölf holst du den Umschlag wieder aus der Jacke.\",\n      \"beleg\": {\n        \"aufenthalt\": {\n          \"person\": \"ahmet\",\n          \"ort\": \"am_jackenstaender\",\n          \"von\": \"23:58:30\",\n          \"bis\": \"23:59:00\"\n        }\n      },\n      \"entlastet\": [\n        \"ahmet\"\n      ],\n      \"grundVerborgen\": \"Er will nicht, dass jemand nach dem Umschlag fragt. Lieber sieht er verdächtig aus.\"\n    },\n    {\n      \"id\": \"b_marek_vor\",\n      \"wer\": \"murat\",\n      \"pfade\": [\n        \"ahmet\",\n        \"fatma\",\n        \"olli\"\n      ],\n      \"art\": \"pfadabhaengig\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Das leuchtende Gesicht rannte an ihm vorbei, bevor es an der Theke schepperte.\",\n      \"duText\": \"Das leuchtende Gesicht rannte an dir vorbei, bevor es an der Theke schepperte.\",\n      \"beleg\": {\n        \"reihenfolge\": [\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:00\",\n            \"bis\": \"00:00:00\"\n          },\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"ev_scheppern\"\n          }\n        ]\n      },\n      \"entlastet\": [\n        \"can\"\n      ],\n      \"trenner\": \"can\",\n      \"grundVerborgen\": \"Er ist sich im Dunkeln nicht sicher und will niemanden falsch belasten.\"\n    },\n    {\n      \"id\": \"b_marek_nach\",\n      \"wer\": \"murat\",\n      \"pfade\": [\n        \"can\"\n      ],\n      \"art\": \"pfadabhaengig\",\n      \"kanal\": \"verborgen\",\n      \"text\": \"Das leuchtende Gesicht rannte an ihm vorbei, nachdem es an der Theke gescheppert hatte.\",\n      \"duText\": \"Das leuchtende Gesicht rannte an dir vorbei, nachdem es an der Theke gescheppert hatte.\",\n      \"beleg\": {\n        \"reihenfolge\": [\n          {\n            \"sinn\": \"hoeren\",\n            \"quelle\": \"ev_scheppern\"\n          },\n          {\n            \"sinn\": \"sehen\",\n            \"quelle\": \"can\",\n            \"detail\": [\n              \"leuchten\"\n            ],\n            \"von\": \"23:58:00\",\n            \"bis\": \"00:00:00\"\n          }\n        ]\n      },\n      \"belastet\": [\n        \"can\"\n      ],\n      \"trenner\": \"can\",\n      \"grundVerborgen\": \"Er ist sich im Dunkeln nicht sicher und will niemanden falsch belasten.\"\n    }\n  ]\n}\n",
  "besetzung.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Besetzungsreihenfolge (F1-ORCH-10). Gezählt werden Rollen ohne den Detektiv (B-13). Bei N Rollen werden die Plätze 1 bis N besetzt; alle übrigen Gäste sind NPC-Gäste ohne Spieler (Weltmodell W1): Sie existieren in der Tatnacht, ihr Wissen erreicht den Detektiv über den Erzähler oder als Fund. Gesprächsmodell „befragung“ (A-051): je Rolle und Runde ein Tischgespräch ohne den Detektiv, höchstens drei Gespräche je Rolle und Runde einschließlich einer Befragung, drei bis fünf Befragungen des Detektivs je Runde.\",\n  \"minRollen\": 4,\n  \"maxRollen\": 20,\n  \"gespraeche\": {\n    \"modell\": \"befragung\",\n    \"tischJeRolle\": 1,\n    \"lastRolle\": 3,\n    \"befragungenJeRunde\": [\n      3,\n      5\n    ]\n  },\n  \"reihenfolge\": [\n    \"ahmet\",\n    \"fatma\",\n    \"olli\",\n    \"can\",\n    \"leyla\",\n    \"emine\",\n    \"tim\",\n    \"johanna\",\n    \"murat\",\n    \"zeynep\",\n    \"baran\",\n    \"meryem\",\n    \"serkan\",\n    \"aylin\",\n    \"kaan\",\n    \"dilara\",\n    \"enes\",\n    \"selin\",\n    \"hakan\",\n    \"tugba\"\n  ],\n  \"stufen\": [\n    {\n      \"stufe\": 1,\n      \"plaetze\": [\n        1,\n        4\n      ]\n    },\n    {\n      \"stufe\": 2,\n      \"plaetze\": [\n        5,\n        8\n      ]\n    },\n    {\n      \"stufe\": 3,\n      \"plaetze\": [\n        9,\n        12\n      ]\n    },\n    {\n      \"stufe\": 4,\n      \"plaetze\": [\n        13,\n        16\n      ]\n    },\n    {\n      \"stufe\": 5,\n      \"plaetze\": [\n        17,\n        20\n      ]\n    }\n  ],\n  \"geschlechterBilanz\": [\n    {\n      \"rollen\": 4,\n      \"m\": 3,\n      \"w\": 1\n    },\n    {\n      \"rollen\": 5,\n      \"m\": 3,\n      \"w\": 2\n    },\n    {\n      \"rollen\": 6,\n      \"m\": 3,\n      \"w\": 3\n    },\n    {\n      \"rollen\": 7,\n      \"m\": 4,\n      \"w\": 3\n    },\n    {\n      \"rollen\": 8,\n      \"m\": 4,\n      \"w\": 4\n    },\n    {\n      \"rollen\": 9,\n      \"m\": 5,\n      \"w\": 4\n    },\n    {\n      \"rollen\": 10,\n      \"m\": 5,\n      \"w\": 5\n    },\n    {\n      \"rollen\": 11,\n      \"m\": 6,\n      \"w\": 5\n    },\n    {\n      \"rollen\": 12,\n      \"m\": 6,\n      \"w\": 6\n    },\n    {\n      \"rollen\": 13,\n      \"m\": 7,\n      \"w\": 6\n    },\n    {\n      \"rollen\": 14,\n      \"m\": 7,\n      \"w\": 7\n    },\n    {\n      \"rollen\": 15,\n      \"m\": 8,\n      \"w\": 7\n    },\n    {\n      \"rollen\": 16,\n      \"m\": 8,\n      \"w\": 8\n    },\n    {\n      \"rollen\": 17,\n      \"m\": 9,\n      \"w\": 8\n    },\n    {\n      \"rollen\": 18,\n      \"m\": 9,\n      \"w\": 9\n    },\n    {\n      \"rollen\": 19,\n      \"m\": 10,\n      \"w\": 9\n    },\n    {\n      \"rollen\": 20,\n      \"m\": 10,\n      \"w\": 10\n    }\n  ],\n  \"regeln\": [\n    \"Die vier Kernverdächtigen sind immer besetzt (Plätze 1–4).\",\n    \"Ab 5 Rollen unterscheiden sich Frauen- und Männerrollen höchstens um eine; bei 4 Rollen geben die Kernnamen 3 zu 1 vor.\",\n    \"Jede Rolle darf von jeder Person gespielt werden, unabhängig vom eigenen Geschlecht.\",\n    \"Fehlt ein Gesprächspartner, übernimmt der erste besetzte Ersatzpartner aus ersatzpartner mit freier Last, sonst die besetzte Rolle mit der kleinsten Last. Der Detektiv sitzt nicht am Tisch; er führt eigene Befragungen. Kernrollen sind immer besetzt und brauchen keinen Ersatz.\",\n    \"Unbesetzte Gäste sind NPC. Was der Detektiv von ihnen braucht, kommt über den Erzähler zum Rundenstart, auch bei Zielfiguren einer Option (E-044), oder als Fund (App: aus dem Kanon, Druck: versiegelt je Fall-Code).\"\n  ],\n  \"ersatzpartner\": {\n    \"leyla\": [\n      \"johanna\",\n      \"aylin\",\n      \"enes\"\n    ],\n    \"emine\": [\n      \"dilara\",\n      \"aylin\"\n    ],\n    \"tim\": [\n      \"enes\",\n      \"murat\"\n    ],\n    \"johanna\": [\n      \"leyla\",\n      \"aylin\"\n    ],\n    \"murat\": [\n      \"zeynep\",\n      \"selin\",\n      \"tim\"\n    ],\n    \"zeynep\": [\n      \"murat\",\n      \"selin\"\n    ],\n    \"baran\": [\n      \"tugba\",\n      \"meryem\"\n    ],\n    \"meryem\": [\n      \"baran\",\n      \"tugba\"\n    ],\n    \"serkan\": [\n      \"baran\",\n      \"tugba\"\n    ],\n    \"aylin\": [\n      \"leyla\",\n      \"johanna\"\n    ],\n    \"kaan\": [\n      \"hakan\",\n      \"dilara\"\n    ],\n    \"dilara\": [\n      \"emine\",\n      \"kaan\"\n    ],\n    \"enes\": [\n      \"tim\",\n      \"leyla\"\n    ],\n    \"selin\": [\n      \"zeynep\",\n      \"murat\"\n    ],\n    \"hakan\": [\n      \"kaan\",\n      \"aylin\"\n    ],\n    \"tugba\": [\n      \"baran\",\n      \"meryem\"\n    ]\n  }\n}\n",
  "entscheidungen.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Die neun Entscheidungen des Detektivs (E-024). Eine Option deckt Fakten auf; ein Fakt erscheint in einem Pfad nur, wenn seine Quelle dort entsteht (Beobachtung mit pfade, Spur mit entstehtWenn). Sonst zeigt die Option die harmlose Fassung der Spur. Die Restverdächtigen folgen allein aus den Regeln und den aufgedeckten Fakten; Bonus-Hinweise zählen nicht (W-1).\",\n  \"regeln\": [\n    {\n      \"id\": \"R-ENTLASTET\",\n      \"wenn\": [\n        \"alibi\",\n        \"nebendelikt\"\n      ],\n      \"folge\": \"entlastet\",\n      \"text\": \"Wer beim Scheppern nachweislich woanders war und zusätzlich eine bewiesene Heimlichtuerei hat, scheidet aus. Beides muss zusammenkommen. Das Scheppern ist das laute Poltern an der Theke, gut eine halbe Minute nach dem Knall.\"\n    },\n    {\n      \"id\": \"R-UEBERFUEHRT\",\n      \"wenn\": [\n        \"schluesselbeweis\",\n        \"fundort\"\n      ],\n      \"folge\": \"ueberfuehrt\",\n      \"text\": \"Ein Schlüsselbeweis überführt eine Person, wenn man auch Herrn Schneiders Schlüsselbund an ihrem Versteck findet. Alle anderen scheiden aus.\"\n    }\n  ],\n  \"fakten\": [\n    {\n      \"id\": \"f_alibi_ahmet\",\n      \"typ\": \"alibi\",\n      \"personen\": [\n        \"ahmet\"\n      ],\n      \"quelle\": {\n        \"beobachtung\": \"b_damir_ahmet_blieb\"\n      }\n    },\n    {\n      \"id\": \"f_spaet_ahmet\",\n      \"typ\": \"spaetankunft\",\n      \"personen\": [\n        \"ahmet\"\n      ],\n      \"quelle\": {\n        \"beobachtung\": \"b_damir_ahmet_weg\"\n      }\n    },\n    {\n      \"id\": \"f_alibi_fatma\",\n      \"typ\": \"alibi\",\n      \"personen\": [\n        \"fatma\"\n      ],\n      \"quelle\": {\n        \"beobachtung\": \"b_emine_fatma_frueh\"\n      }\n    },\n    {\n      \"id\": \"f_spaet_fatma\",\n      \"typ\": \"spaetankunft\",\n      \"personen\": [\n        \"fatma\"\n      ],\n      \"quelle\": {\