\": \"e2_1_ascheneimer\",\n        \"can\": \"e2_1_bauchtasche\"\n      },\n      \"begruendung\": {\n        \"ahmet\": {\n          \"kette\": [\n            \"fakt:f_spaet_ahmet\",\n            \"beobachtung:b_hana_umschlag\"\n          ],\n          \"text\": \"Ahmet war beim Scheppern nicht bei Damir. Hana sah ihn kurz nach zwölf etwas in den Ascheneimer werfen.\"\n        },\n        \"fatma\": {\n          \"kette\": [\n            \"fakt:f_alibi_ahmet\",\n            \"beobachtung:b_lejla_ahmet_theke\",\n            \"beobachtung:b_hana_umschlag\",\n            \"luege:luege_ahmet_servietten\"\n          ],\n          \"text\": \"Ahmet war beim Scheppern bei Damir, hat aber wegen seines Umschlags gelogen. Was er in den Ascheneimer warf, erklärt das.\"\n        },\n        \"olli\": {\n          \"kette\": [\n            \"fakt:f_alibi_ahmet\",\n            \"beobachtung:b_lejla_ahmet_theke\",\n            \"beobachtung:b_hana_umschlag\",\n            \"luege:luege_ahmet_servietten\"\n          ],\n          \"text\": \"Ahmet war beim Scheppern bei Damir, hat aber wegen seines Umschlags gelogen. Was er in den Ascheneimer warf, erklärt das.\"\n        },\n        \"can\": {\n          \"kette\": [\n            \"fakt:f_alibi_fatma\",\n            \"fakt:f_alibi_olli\",\n            \"beobachtung:b_marek_gesicht\",\n            \"merkmal:can\"\n          ],\n          \"text\": \"Fatma und Olli haben ein Alibi für das Scheppern, Ahmet und Can nicht. Marek sah ein leuchtendes Gesicht, und Cans Hand steckt tief in der Bauchtasche seines Pullis.\"\n        }\n      }\n    },\n    {\n      \"id\": \"e2_2\",\n      \"runde\": 2,\n      \"nr\": 2,\n      \"art\": \"gegenstand\",\n      \"frage\": \"Was untersuchst du als Nächstes?\",\n      \"optionen\": [\n        {\n          \"id\": \"e2_2_vitrine\",\n          \"ziel\": {\n            \"gegenstand\": \"vitrine\"\n          },\n          \"text\": \"Die Vitrine im Turmgang untersuchen\",\n          \"fakten\": [\n