   },\n    {\n      \"id\": \"e3_1\",\n      \"runde\": 3,\n      \"nr\": 1,\n      \"art\": \"ort\",\n      \"frage\": \"Wo suchst du nach Herrn Schneiders Schlüsselbund?\",\n      \"optionen\": [\n        {\n          \"id\": \"e3_1_turmgang\",\n          \"ziel\": {\n            \"raum\": \"turmgang\",\n            \"ort\": \"an_der_ruestung\"\n          },\n          \"text\": \"Im Turmgang bei der Rüstung suchen\",\n          \"fakten\": [\n            \"f_fundort_can\"\n          ]\n        },\n        {\n          \"id\": \"e3_1_ostsaal\",\n          \"ziel\": {\n            \"raum\": \"ost_saal\",\n            \"ort\": \"am_jackenstaender\"\n          },\n          \"text\": \"Im Ost-Saal mit dem Jackenständer suchen\",\n          \"fakten\": [\n            \"f_fundort_ahmet\"\n          ]\n        },\n        {\n          \"id\": \"e3_1_buffetsaal\",\n          \"ziel\": {\n            \"raum\": \"thekensaal\",\n            \"ort\": \"vor_theke\"\n          },\n          \"text\": \"Im Buffetsaal an Theke und Buffettischen suchen\",\n          \"fakten\": [\n            \"f_fundort_fatma\",\n            \"f_fundort_olli\"\n          ]\n        }\n      ],\n      \"richtig\": {\n        \"ahmet\": \"e3_1_ostsaal\",\n        \"fatma\": \"e3_1_buffetsaal\",\n        \"olli\": \"e3_1_buffetsaal\",\n        \"can\": \"e3_1_turmgang\"\n      },\n      \"begruendung\": {\n        \"ahmet\": {\n          \"kette\": [\n            \"fakt:f_spaet_ahmet\",\n            \"fakt:f_z_ahmet\",\n            \"karte:jacke_ahmet\"\n          ],\n          \"text\": \"Ahmet war beim Scheppern weg, und an seinem Umschlag klebt Wachs vom Tatort. Seine Jacke hängt im Ost-Saal.\"\n        },\n        \"fatma\": {\n          \"kette\": [\n            \"fakt:f_spaet_fatma\",\n            \"fakt:f_z_fatma\",\n            \"beobachtung:b_emine_versteck\",\n            \"karte:brottasche\"\n          ],\n          \"text\": \"Fatma kam erst nach dem Scheppern zum linken Buffettisch, un