nder\"\n          ],\n          \"text\": \"An Ahmets Umschlag ist Wachs vom Tatort, und eine Ecke fehlt. Vielleicht ist sie am Kerzenständer geblieben.\"\n        },\n        \"fatma\": {\n          \"kette\": [\n            \"fakt:f_z_fatma\",\n            \"merkmal:fatma\"\n          ],\n          \"text\": \"Auf der Schatulle in Fatmas Tasche ist Wachs vom Tatort. Ihr breiter Silberring trifft beim Zupacken auf das Messing.\"\n        },\n        \"olli\": {\n          \"kette\": [\n            \"fakt:f_z_olli\",\n            \"merkmal:olli\",\n            \"karte:kerzenstaender\"\n          ],\n          \"text\": \"An Ollis Handschuh ist Wachs vom Tatort, an seinen Ärmeln hängen Splitter und Kalk. Der Kerzenständer zeigt, ob davon etwas im Wachs klebt.\"\n        },\n        \"can\": {\n          \"kette\": [\n            \"fakt:f_z_can\",\n            \"fakt:f_nd_can_maske\",\n            \"karte:kerzenstaender\"\n          ],\n          \"text\": \"An Cans Maske ist Wachs vom Tatort, und ihre Leuchtfarbe ist noch klebrig. Wer so den Kerzenständer packt, hinterlässt Farbe.\"\n        }\n      }\n    },\n    {\n      \"id\": \"e3_3\",\n      \"runde\": 3,\n      \"nr\": 3,\n      \"art\": \"person\",\n      \"frage\": \"Mit wem sprichst du zuletzt?\",\n      \"optionen\": [\n        {\n          \"id\": \"e3_3_zeynep\",\n          \"ziel\": {\n            \"person\": \"zeynep\"\n          },\n          \"text\": \"Zeynep befragen\",\n          \"fakten\": [\n            \"f_nd_can_zeynep\"\n          ]\n        },\n        {\n          \"id\": \"e3_3_aylin\",\n          \"ziel\": {\n            \"person\": \"aylin\"\n          },\n          \"text\": \"Aylin nach ihrem Beleg fragen\",\n          \"fakten\": [\n            \"f_nd_ahmet_quittung\"\n          ]\n        }\n      ],\n      \"richtig\": {\n        \"ahmet\": \"e3_3_zeynep\",\n        \"fatma\": \"e3_3_zeynep\",\n        \"olli\": \"e3_3_zeynep\",\n        \"can\": \"e3_3_aylin\"\n      },\n      \"