  "bonus.json": "{\n  \"settingId\": \"spuk_im_schlosskeller\",\n  \"hinweis\": \"Bonus-Hinweise je Pfad, Runde und Qualität (E-024, E-025). Alle erscheinen im selben Rahmen ohne Quelle; je Runde haben die Hinweise möglichst dieselbe Satzform. Vor der Auflösung wird weder die Qualität noch die Stimmenzahl gezeigt. Wahr: ein wahrer Baustein, der nie allein ausschließt (W-1). Neutral: wahre, pfadgleiche Sätze ohne neuen Wert. Falsch: ein Gerücht über einen Unschuldigen, widerlegt durch eine im Pfad richtige Entscheidung.\",\n  \"hinweise\": [\n    {\n      \"id\": \"h_ahmet_1_wahr\",\n      \"pfad\": \"ahmet\",\n      \"runde\": 1,\n      \"qualitaet\": \"wahr\",\n      \"text\": \"Beim Scheppern war Ahmet nicht bei Damir am Ostende der Theke.\",\n      \"wirkung\": {\n        \"art\": \"belastet\",\n        \"person\": \"ahmet\"\n      },\n      \"quelle\": [\n        \"beobachtung:b_damir_ahmet_weg\"\n      ]\n    },\n    {\n      \"id\": \"h_ahmet_1_neutral\",\n      \"pfad\": \"ahmet\",\n      \"runde\": 1,\n      \"qualitaet\": \"neutral\",\n      \"text\": \"Im Dunkeln huschte ein leuchtendes Gesicht am Sicherungskasten vorbei.\",\n      \"wirkung\": {\n        \"art\": \"neutral\"\n      },\n      \"quelle\": [\n        \"beobachtung:b_tim_gesicht\"\n      ]\n    },\n    {\n      \"id\": \"h_ahmet_1_falsch\",\n      \"pfad\": \"ahmet\",\n      \"runde\": 1,\n      \"qualitaet\": \"falsch\",\n      \"text\": \"Beim Scheppern war Olli nicht bei Azra am rechten Buffettisch.\",\n      \"wirkung\": {\n        \"art\": \"belastet\",\n        \"person\": \"olli\"\n      },\n      \"widerlegtDurch\": [\n        \"e1_3_azra\"\n      ]\n    },\n    {\n      \"id\": \"h_ahmet_2_wahr\",\n      \"pfad\": \"ahmet\",\n      \"runde\": 2,\n      \"qualitaet\": \"wahr\",\n      \"text\": \"Ahmet hat um neun vor zwölf an der Theke mit Herrn Schneider über die Miete gestritten.\",\n      \"wirkung\": {\n        \"art\": \"belastet\",\n        \"person\": \"ahmet\"\n      },\n    